properties.query:
let threshold = 10;
// Must stay <= queryPeriod. Wider than queryFrequency so a burst that straddles two runs
// still reaches the threshold.
let lookback = 1h;
// Must equal queryFrequency. A user is only evaluated when a secret event of theirs was
// ingested since the previous run, so the next run does not re-alert on a burst it has
// already counted - see 'Delinea - Failed authentication spike'.
let newSince = 30m;
let secretEventPattern = @"(?i)\.Secret\.(Viewed|Exported|Downloaded|Retrieved|Copied)";
let secretEvents =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(lookback)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | extend EventName = tostring(d.eventType.name), SrcIP = tostring(d.source.host.network.ipAddress)
    | where EventName matches regex secretEventPattern;
let recentUsers = secretEvents | where IngestedAt > ago(newSince) | distinct User;
secretEvents
| where User in (recentUsers)
| extend IsExport = EventName has_any ("Exported", "Downloaded", "Retrieved", "Copied")
| summarize DistinctSecrets = dcount(SecretId), Secrets = make_set(SecretId, 50),
            TotalOperations = count(), Exports = countif(IsExport), Secret = take_any(SecretId),
            StartTime = min(TimeGenerated), EndTime = max(TimeGenerated)
        by User, SrcIP
| where DistinctSecrets >= threshold
| sort by DistinctSecrets desc

let threshold = 10;
// The data collection rule sets TimeGenerated from the Delinea eventDateTime and the
// connector polls in 5 minute windows, so events routinely land several minutes after
// the time they carry. 'lookback' must stay <= queryPeriod and must be wide enough to
// absorb that lag, otherwise late arriving events are never evaluated by any run.
let lookback = 1h;
// Must equal queryFrequency so every event is counted by exactly one run.
let newSince = 15m;
// Authentication events only. Matched against eventType.name, falling back to
// internalName, the same way ASimAuditEventDelineaPlatform resolves the event name.
let authEventPattern = @"(?i)mfa|multifactor|\blogin\b|\blogon\b|signin|authentication";
let failures =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(lookback)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | extend Attr = d.additionalAttributes
    | extend EventName = tostring(coalesce(d.eventType.name, d.eventType.internalName))
    | where EventName matches regex authEventPattern
    // The attributes bag carries either scalars or single element arrays depending on
    // the reporting service, so both shapes are read - see ASimAuditEventDelineaPlatform.
    | extend Actor = tostring(coalesce(d.actor.email, d.actor.name, d.actor.displayName)),
             RawSrcIP = tostring(d.source.host.network.ipAddress),
             MfaResult = tostring(coalesce(Attr.MfaResult[0], Attr.MfaResult)),
             FactorPassword = tostring(coalesce(Attr.FactorPassword[0], Attr.FactorPassword)),
             FailReason = tostring(coalesce(Attr.FailReason[0], Attr.FailReason))
    | where MfaResult =~ "Failed" or FactorPassword =~ "Failed" or isnotempty(FailReason)
    | where isnotempty(Actor)
    // '0.0.0.0' is the placeholder reported for events that have no network origin.
    | extend SrcIP = iff(RawSrcIP in ("", "0.0.0.0"), "", RawSrcIP);
let recentActors = failures | where IngestedAt > ago(newSince) | distinct Actor;
failures
| where Actor in (recentActors)
| summarize Failures = count(), DistinctSourceIPs = dcountif(SrcIP, isnotempty(SrcIP)),
            SourceIPs = make_set_if(SrcIP, isnotempty(SrcIP), 20),
            FailReasons = make_set_if(FailReason, isnotempty(FailReason), 10),
            SrcIP = take_anyif(SrcIP, isnotempty(SrcIP)),
            StartTime = min(TimeGenerated), EndTime = max(TimeGenerated) by Actor
| where Failures >= threshold
| project Actor, Failures, DistinctSourceIPs, SourceIPs, FailReasons, SrcIP, StartTime, EndTime
| sort by Failures desc

let detectionWindow = 1h;   // must equal queryFrequency
let baseline = 14d;         // must stay <= queryPeriod
// Delinea exposes no in-band sensitivity flag - tags and analyticData are null on every
// secret event - so value is inferred from the secret name and its folder. Secret Server
// permissions are inherited from folder placement, which makes containerName the strongest
// tiering signal, and it exists only inside notes: top-level target.containerName is null.
//
// TUNING 1 of 2: common high-value naming conventions, matched as a case insensitive
// substring against both the secret name and its folder. Trim groups that are noisy in
// your tenant; add cloud and CI terms (azure, aws, gcp, jenkins, ansible, terraform) only
// if those secrets are genuinely privileged, as they match broadly.
let sensitivePattern = @"(?i)admin|administrator|\broot\b|sudo|superuser|breakglass|break.?glass|emergency|privileged|\bpriv\b|\bda\b|\bea\b|domain.?admin|enterprise.?admin|\bsa[-_]|\bsvc[-_]|service.?account|\bprod\b|production|\bprd\b|backup|restore|disaster|\bdr\b|domain.?controller|\bdc\d|firewall|router|esxi|vcenter|hypervisor|\bsql\b|mysql|mssql|postgres|oracle|mongo|\bdba\b|\bkey\b|api.?key|keystore|vault|token|credential|password|passwd|\bpwd\b|cert\b|certificate|\bpki\b|ssh|rdp|winrm";
// TUNING 2 of 2: tenant specific names, filled in at deployment time. Exact match, case
// insensitive - use sensitivePattern above for substring matching. Leave empty if unused.
let customSecretNames = dynamic([]);
//   e.g. dynamic(["Break Glass Account", "ESXi root", "SAP_PROD_ADMIN"]);
let customFolders = dynamic([]);
//   e.g. dynamic(["Tier 0", "Domain Admins", "Production Databases"]);
let access =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(baseline)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | where tostring(d.eventType.name) == "Delinea.Vault.Secret.Viewed"
    // notes is a JSON document carried as a string - same idiom as
    // Workbooks/DelineaSecretServerVaultActivity.json
    | extend n = parse_json(tostring(d.notes))
    | extend Actor = tostring(coalesce(d.actor.name, d.actor.email, d.actor.displayName)),
             ActorEmail = tostring(d.actor.email),
             SecretKey = tostring(coalesce(d.target.id, d.target.platformId, n.itemId)),
             // Trimmed because these become entity identifiers - Delinea returns names
             // such as '10.60.25.30 MYSQL ' with trailing whitespace.
             SecretName = trim(@'\s', coalesce(tostring(d.target.displayName), tostring(d.target.name),
                                   tostring(n.itemNameForDisplay), tostring(n.itemName), SecretId)),
             Folder = trim(@'\s', tostring(n.containerName)),
             Details = tostring(n.eventDetails),
             RawSrcIP = tostring(coalesce(d.source.host.network.ipAddress, n.ipAddress))
    // eventDetails is free text: " Account Name: qa-e2e-target  Target Server: 10.60.25.51 "
    | extend AccountName = extract(@'Account Name:\s*(.*?)\s*(?:Target Server:|$)', 1, Details),
             TargetServer = extract(@'Target Server:\s*(.*?)\s*$', 1, Details)
    | extend SrcIP = iff(RawSrcIP in ("", "0.0.0.0"), "", RawSrcIP)
    | where isnotempty(Actor) and isnotempty(SecretKey)
    // To rely on the custom lists alone, delete the two 'matches regex' clauses - do not
    // blank sensitivePattern, an empty regex matches every row.
    | where SecretName matches regex sensitivePattern
         or Folder matches regex sensitivePattern
         or SecretName in~ (customSecretNames)
         or Folder in~ (customFolders);
// Batch by ingestion time so a late arriving event is still evaluated exactly once.
let priorAccess = access | where IngestedAt <= ago(detectionWindow) | distinct Actor, SecretKey;
access
| where IngestedAt > ago(detectionWindow)
| join kind=leftanti priorAccess on Actor, SecretKey
| summarize FirstAccess = min(TimeGenerated), LastAccess = max(TimeGenerated), Accesses = count(),
            SecretName = take_any(SecretName), Folder = take_any(Folder),
            ActorEmail = take_anyif(ActorEmail, isnotempty(ActorEmail)),
            AccountNames = make_set_if(AccountName, isnotempty(AccountName), 10),
            TargetServers = make_set_if(TargetServer, isnotempty(TargetServer), 10),
            TargetServer = take_anyif(TargetServer, isnotempty(TargetServer)),
            SourceIPs = make_set_if(SrcIP, isnotempty(SrcIP), 20),
            SrcIP = take_anyif(SrcIP, isnotempty(SrcIP))
        by Actor, SecretKey
// 'Target Server' is reported as either an address or a hostname, so each row feeds
// whichever entity fits and blanks the other. Sentinel skips empty entity values.
| extend TargetIsIp = isnotnull(parse_ipv4(TargetServer)) or isnotnull(parse_ipv6(TargetServer))
| extend TargetIP = iff(TargetIsIp, TargetServer, ""),
         TargetHost = iff(TargetIsIp, "", TargetServer)
| project FirstAccess, LastAccess, Actor, ActorEmail, SecretKey, SecretName, Folder,
          AccountNames, TargetServers, TargetHost, TargetIP, Accesses, SourceIPs, SrcIP
| sort by FirstAccess desc

let detectionWindow = 1h;   // must equal queryFrequency
let baseline = 14d;         // must stay <= queryPeriod
// TUNING 1 of 2: the event name must name a privileged object AND end in a grant-type verb.
// Bare 'member', 'assign', 'owner' and 'group' are deliberately absent - they match
// routine directory user and group activity.
let escalationObjects = @"(?i)role|permission|privilege|admin|rights|entitlement|elevat|justintime";
let grantVerbs = @"(?i)(Added|Assigned|Granted|Elevated|Approved|Created|Updated|Modified|Changed)$";
// TUNING 2 of 2: tenant specific exclusions, filled in at deployment time. Exact match,
// case insensitive. Leave empty if unused.
let excludedEventNames = dynamic([]);
//   e.g. dynamic(["Delinea.Vault.Group.Updated"]);
let excludedServiceTypes = dynamic([]);
//   e.g. dynamic(["Identity"]);
let excludedActors = dynamic([]);
//   e.g. dynamic(["svc-directory-sync"]);
let grants =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(baseline)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | extend EventName = tostring(coalesce(d.eventType.name, d.eventType.internalName))
    | where EventName matches regex escalationObjects and EventName matches regex grantVerbs
    | extend Actor = tostring(coalesce(d.actor.name, d.actor.email, d.actor.displayName)),
             ServiceType = tostring(d.service.type),
             Target = tostring(coalesce(d.target.displayName, d.target.name)),
             // ID first - display names can change. Empty when the event carries no target.
             TargetKey = tostring(coalesce(d.target.id, d.target.platformId, d.target.name, d.target.displayName)),
             FieldChanges = tostring(d.fieldChanges),
             RawSrcIP = tostring(d.source.host.network.ipAddress)
    | where isnotempty(Actor)
    | where not(EventName in~ (excludedEventNames))
        and not(ServiceType in~ (excludedServiceTypes))
        and not(Actor in~ (excludedActors))
    // '0.0.0.0' is the placeholder reported for events that have no network origin.
    | extend SrcIP = iff(RawSrcIP in ("", "0.0.0.0"), "", RawSrcIP);
// Batch by ingestion time so a late arriving event is still evaluated exactly once.
// The baseline is keyed on the target too, so repeating a grant on the same target is
// suppressed but the same grant against a new target still alerts.
let priorGrants = grants | where IngestedAt <= ago(detectionWindow) | distinct Actor, EventName, TargetKey;
grants
| where IngestedAt > ago(detectionWindow)
| join kind=leftanti priorGrants on Actor, EventName, TargetKey
| summarize Changes = count(), EventNames = make_set(EventName, 20),
            Targets = make_set_if(Target, isnotempty(Target), 20),
            FieldChanges = make_list_if(FieldChanges, isnotempty(FieldChanges), 10),
            SourceIPs = make_set_if(SrcIP, isnotempty(SrcIP), 20),
            SrcIP = take_anyif(SrcIP, isnotempty(SrcIP)),
            StartTime = min(TimeGenerated), EndTime = max(TimeGenerated) by Actor
| project StartTime, EndTime, Actor, Changes, EventNames, Targets, FieldChanges, SourceIPs, SrcIP
| sort by StartTime desc

let detectionWindow = 1h;   // must equal queryFrequency
let baseline = 14d;         // must stay <= queryPeriod
// TUNING 1 of 2: configuration objects worth alerting on, matched against the event name.
// Generic terms such as 'setting', 'profile', 'configuration', 'connector' and 'integration'
// are deliberately absent - they match routine directory and user-profile activity.
let configPattern = @"(?i)authenticationprofile|authprofile|authentication\.profile|polic(y|ies)|(^|[^a-z])sso|saml|oidc|oauth|federation|identityprovider|(^|[^a-z])idp|iprange|iprestriction|ipallowlist|webhook|config";
// Event names end in the verb (Delinea.Vault.Secret.Viewed, or PascalCase), so read-only
// events never match this.
let changeVerbs = @"(?i)(Added|Created|Updated|Modified|Changed|Set|Deleted|Removed|Enabled|Disabled|Configured|Update|Change)$";
// TUNING 2 of 2: tenant specific exclusions, filled in at deployment time. Exact match,
// case insensitive. Leave empty if unused.
let excludedEventNames = dynamic(["Delinea.Cloud.Core.Data.ProxyState.Changed"]);
//   e.g. dynamic(["Delinea.Vault.Group.Updated"]);
let excludedServiceTypes = dynamic([]);
//   e.g. dynamic(["Identity"]);
let excludedActors = dynamic([]);
//   e.g. dynamic(["svc-directory-sync"]);
let changes =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(baseline)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | extend EventName = tostring(coalesce(d.eventType.name, d.eventType.internalName))
    | where EventName matches regex configPattern and EventName matches regex changeVerbs
    | extend Actor = tostring(coalesce(d.actor.name, d.actor.email, d.actor.displayName)),
             ServiceType = tostring(d.service.type),
             Target = tostring(coalesce(d.target.displayName, d.target.name)),
             FieldChanges = tostring(d.fieldChanges),
             RawSrcIP = tostring(d.source.host.network.ipAddress)
    | where isnotempty(Actor)
    | where not(EventName in~ (excludedEventNames))
        and not(ServiceType in~ (excludedServiceTypes))
        and not(Actor in~ (excludedActors))
    // '0.0.0.0' is the placeholder reported for events that have no network origin.
    | extend SrcIP = iff(RawSrcIP in ("", "0.0.0.0"), "", RawSrcIP);
// Batch by ingestion time so a late arriving event is still evaluated exactly once.
let priorChanges = changes | where IngestedAt <= ago(detectionWindow) | distinct Actor, EventName;
changes
| where IngestedAt > ago(detectionWindow)
| join kind=leftanti priorChanges on Actor, EventName
| summarize Changes = count(), EventNames = make_set(EventName, 20),
            Targets = make_set_if(Target, isnotempty(Target), 20),
            FieldChanges = make_list_if(FieldChanges, isnotempty(FieldChanges), 10),
            SourceIPs = make_set_if(SrcIP, isnotempty(SrcIP), 20),
            SrcIP = take_anyif(SrcIP, isnotempty(SrcIP)),
            StartTime = min(TimeGenerated), EndTime = max(TimeGenerated) by Actor
| project StartTime, EndTime, Actor, Changes, EventNames, Targets, FieldChanges, SourceIPs, SrcIP
| sort by StartTime desc
